SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, SUM(CASE WHEN method = 'promptpay' THEN 1 ELSE 0 END) AS promptpay_count FROM payments WHERE method IN ('paypal', 'card') GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING promptpay_count < 29;
